# ---------- 2. weights ----------
me=ob.data; Mo=ob.matrix_world
co=[Mo@v.co for v in me.vertices]
segs={n:(Vector(h),Vector(t)) for n,(h,t,p) in RB.items()}
def segd(p,a,b):
    ab=b-a; t=max(0.0,min(1.0,(p-a).dot(ab)/ab.length_squared)); return (p-(a+ab*t)).length
# spear axis from the isolated upper shaft (y>0.05, x>0.12, z>0.58)
U=[i for i,p in enumerate(co) if p.y>0.05 and p.x>0.12 and p.z>0.58]
top=max(U,key=lambda i:co[i].z); bot=min(U,key=lambda i:co[i].z)
ax=(co[top]-co[bot]).normalized(); a0=co[bot]
print("SPEAR upper n=%d top=%s bot=%s axis=%s"%(len(U),tuple(round(c,3) for c in co[top]),tuple(round(c,3) for c in co[bot]),tuple(round(c,3) for c in ax)))
def linedist(p):
    d=p-a0; return (d-ax*d.dot(ax)).length
def along(p): return (p-a0).dot(ax)
# shaft: within 0.022 of the axis; blade (above the grip, along>0.05): within 0.045 (blade half-width measured 0.04, nothing else up there)
spear=set(i for i,p in enumerate(co) if p.y>0.04 and 0.40<=p.z<=0.86 and (linedist(p)<0.022 or (along(p)>0.05 and linedist(p)<0.045)))
# lower shaft (below the grip, fused with fist and wolf mane): constrained flood along mesh edges, tube radius only
import collections as _c
_adj=_c.defaultdict(set)
for _e in me.edges: _adj[_e.vertices[0]].add(_e.vertices[1]); _adj[_e.vertices[1]].add(_e.vertices[0])
_fr=list(spear); _added=0
while _fr:
    _nf=[]
    for _i in _fr:
        for _j in _adj[_i]:
            _p=co[_j]
            if _j not in spear and _p.y>0.0 and -0.26<along(_p)<0.05 and linedist(_p)<0.02:
                spear.add(_j); _nf.append(_j); _added+=1
    _fr=_nf
print("SPEAR flood added", _added, "zmin %.3f"%min(co[i].z for i in spear))
low=[co[i] for i in spear if co[i].z<0.50]
print("SPEAR verts", len(spear), "low part n=%d"%len(low), "low bbox", [tuple(round(min(c[k] for c in low),3) for k in range(3)), tuple(round(max(c[k] for c in low),3) for k in range(3))] if low else None)
def is_rider(p):
    if p.z>0.515 and -0.10<along(p)<0.12 and linedist(p)<0.065: return True   # fist, thumb and shaft binding beside the grip (x>0.20)
    if p.z<=0.44 or p.x<-0.13 or p.x>0.20 or abs(p.y)>0.16: return False
    if p.x>0.13 and abs(p.y)<0.08 and p.z<0.58: return False   # wolf mane / neck ridge
    return True
cand=[i for i,p in enumerate(co) if is_rider(p)]
print("RIDER cand", len(cand))
vgs={n:ob.vertex_groups.new(name=n) for n in RB}
gidx={g.index:g for g in ob.vertex_groups}
# geodesic weights (v2): multi-source Dijkstra over mesh edges from each bone's core verts, rider verts only, spear excluded.
# Straight-line nearest-segment weights (v1) pulled chest verts beside the armpit up with the arm and tore the shoulder.
import heapq, os
RCORE={'R_Hips':0.07,'R_Spine':0.06,'R_Spine1':0.06,'R_Spine2':0.06,'R_Neck':0.035,'R_Head':0.06,
 'R_LShoulder':0.03,'R_LArm':0.035,'R_LForeArm':0.03,'R_LHand':0.03,'R_RShoulder':0.03,'R_RArm':0.035,'R_RForeArm':0.03,'R_RHand':0.03}
candset=set(cand)-spear
G={}
for n,(a,b) in segs.items():
    src=[i for i in candset if segd(co[i],a,b)<RCORE[n]]
    if len(src)<5: src=sorted(candset,key=lambda i:segd(co[i],a,b))[:20]
    dist={i:segd(co[i],a,b) for i in src}
    pq=[(d,i) for i,d in dist.items()]; heapq.heapify(pq)
    while pq:
        d,i=heapq.heappop(pq)
        if d>dist.get(i,1e9): continue
        for j in _adj[i]:
            if j not in candset: continue
            nd=d+(co[i]-co[j]).length
            if nd<dist.get(j,1e9): dist[j]=nd; heapq.heappush(pq,(nd,j))
    G[n]=dist; print("GEO",n,"core",len(src),"reached",len(dist))
SIG=float(os.environ.get("WSIG","0.006")); W={}; _unr=0
# v4: an arm bone may only own verts inside its capsule (Tripo fused forearm->belly and fist->mane; geodesics leak through the contact)
RMAX={"R_LArm":0.075,"R_LForeArm":0.055,"R_LHand":0.075,"R_RArm":0.075,"R_RForeArm":0.055,"R_RHand":0.075,"R_LShoulder":0.10,"R_RShoulder":0.10}
for i in candset:
    ds=sorted((G[n].get(i,1e9),n) for n in segs); d1=ds[0][0]
    if d1>1e8:
        _unr+=1; ds=sorted((segd(co[i],a,b),n) for n,(a,b) in segs.items()); d1=ds[0][0]
    ds=[(d,n) for d,n in ds if n not in RMAX or segd(co[i],*segs[n])<RMAX[n]] or ds; d1=ds[0][0]
    ws={n:math.exp(-(d-d1)/SIG) for d,n in ds[:3] if d-d1<3*SIG}
    s_=sum(ws.values()); W[i]={n:w/s_ for n,w in ws.items()}
print("GEO unreached", _unr)
for _it in range(int(os.environ.get("WSMOOTH","1"))):
    W2={}
    for i in candset:
        nb=[j for j in _adj[i] if j in candset]; acc=_c.defaultdict(float)
        for n,w in W[i].items(): acc[n]+=0.5*w
        for j in nb:
            for n,w in W[j].items(): acc[n]+=0.5*w/len(nb)
        top=sorted(acc.items(),key=lambda kv:-kv[1])[:3]; s_=sum(w for _,w in top)
        W2[i]={n:w/s_ for n,w in top}
    W=W2
_LOW={'R_LForeArm','R_LHand','R_RForeArm','R_RHand'}; _ARM=_LOW|{'R_LArm','R_RArm'}; _purged=0
for i in candset:
    o=max(W[i],key=W[i].get)
    keep={n:w for n,w in W[i].items() if (n in _ARM)==(o in _ARM)} if (o in _LOW or o not in _ARM) else W[i]
    if len(keep)<len(W[i]): _purged+=1; s_=sum(keep.values()); W[i]={n:w/s_ for n,w in keep.items()}
print('SEAM purged', _purged)
assign={}
for i in cand+list(spear):
    p=co[i]
    new={'R_LHand':1.0} if i in spear else W[i]
    t=1.0 if i in spear else max(0.0,min(1.0,(p.z-0.44)/0.05))   # blend into the saddle weights near the seat
    old=[(g.group,g.weight) for g in me.vertices[i].groups]
    osum=sum(w for _,w in old) or 1.0
    for g,w in old: gidx[g].add([i],w/osum*(1-t),'REPLACE')
    for n,w in new.items(): vgs[n].add([i],w*t,'REPLACE')
    assign[i]=max(new,key=new.get)
print("ASSIGN", sorted(Counter(assign.values()).items()))
_FR=float(os.environ.get("FISTR","0.13")); _fx=0; _cs=set(cand)|set(spear)
for i,p in enumerate(co):
    if i in _cs or p.z<0.44 or segd(p,*segs['R_LHand'])>=_FR: continue
    if p.x>segs["R_LHand"][0].x+float(os.environ.get("FISTFX","0.03")) and p.z<segs["R_LHand"][0].z-float(os.environ.get("FISTDZ","0.02")): continue   # reins run forward from the fist: leave them on the wolf head
    _t=1.0
    _old=[(g.group,g.weight) for g in me.vertices[i].groups]; _os=sum(w for _,w in _old) or 1.0
    for g,w in _old: gidx[g].add([i],w/_os*(1-_t),'REPLACE')
    vgs['R_LHand'].add([i],_t,'REPLACE'); _fx+=1
print("FIST fixed", _fx)

# ---------- 2b. front-left lower leg bones ----------
bpy.context.view_layer.objects.active=arm; bpy.ops.object.mode_set(mode='EDIT'); _eb=arm.data.edit_bones
for _n,_h,_t,_p in (('L_fore',(0.07,0.075,0.16),(0.01,0.065,0.05),'bone_13'),('L_paw',(0.01,0.065,0.05),(0.05,0.07,0.0),'L_fore')):
    _e=_eb.new(_n); _e.head=Mwi@Vector(_h); _e.tail=Mwi@Vector(_t); _e.parent=_eb[_p]; _e.use_connect=False; _e.use_deform=True
bpy.ops.object.mode_set(mode='OBJECT')
_gn={g.index:g.name for g in ob.vertex_groups}; _S={'tripo::Spine_3','bone_35','bone_13','bone_12'}
_gf=ob.vertex_groups.new(name='L_fore'); _gp=ob.vertex_groups.new(name='L_paw'); _Wo=ob.matrix_world; _nl=0
for v in me.vertices:
    p=_Wo@v.co
    if not (p.y>0.02 and -0.06<p.x<0.14 and p.z<0.17 and v.groups): continue
    if _gn[max(v.groups,key=lambda g:g.weight).group] not in _S: continue
    for g in list(v.groups):
        if _gn[g.group] in _S: ob.vertex_groups[g.group].remove([v.index])
    if p.z<0.04: _gp.add([v.index],1.0,'REPLACE')
    elif p.z<0.06: t=(p.z-0.04)/0.02; _gp.add([v.index],1-t,'REPLACE'); _gf.add([v.index],t,'REPLACE')
    elif p.z<0.14: _gf.add([v.index],1.0,'REPLACE')
    else: t=(p.z-0.14)/0.03; _gf.add([v.index],1-t,'REPLACE'); ob.vertex_groups['bone_13'].add([v.index],t,'REPLACE')
    _nl+=1
print("LLEG reweighted", _nl)
# v8f: near front leg bones may only own verts inside a capsule around the leg; chest/throat verts go to Spine_3
_CR=float(os.environ.get("LEGCAP","0.055")); _gn={g.index:g.name for g in ob.vertex_groups}; _sp=ob.vertex_groups['tripo::Spine_3']; _nc=0
_seg=lambda n:(arm.matrix_world@arm.data.bones[n].head_local, arm.matrix_world@arm.data.bones[n].tail_local)
def _sd(p,a,b):
    ab=b-a; t=max(0,min(1,(p-a).dot(ab)/max(ab.length_squared,1e-9))); return (p-(a+ab*t)).length
for v in me.vertices:
    p=_Wo@v.co
    for gi,w in [(g.group,g.weight) for g in v.groups]:
        n=_gn[gi]
        if n in tuple(os.environ.get('LEGBONES','bone_15,bone_16,bone_12,bone_13').split(',')) and _sd(p,*_seg(n))>_CR:
            ob.vertex_groups[gi].remove([v.index]); _sp.add([v.index],w,'ADD'); _nc+=1
print("LEGCAP moved", _nc)

# ---------- 3. sample the source clips ----------
def import_fbx(path,name):
    before=set(bpy.data.objects); bpy.ops.import_scene.fbx(filepath=path,use_anim=True,use_image_search=False)
    new=[o for o in bpy.data.objects if o not in before]; a=[o for o in new if o.type=='ARMATURE'][0]; a.name=name; return a,new
def qof(a,pb): return (a.matrix_world@pb.matrix).to_3x3().normalized().to_quaternion()
def sample(a,act,frames,bones,root):
    a.animation_data.action=act
    if act.slots: a.animation_data.action_slot=act.slots[0]
    out=[]
    for f in frames:
        fi=int(math.floor(f)); sc.frame_set(fi,subframe=f-fi); bpy.context.view_layer.update()
        out.append(({b:qof(a,a.pose.bones[b]) for b in bones if b in a.pose.bones},(a.matrix_world@a.pose.bones[root].matrix).translation.copy()))
    return out
WMAP={ # tripo bone -> fantasy wolf bone, matched by joint position. tripo::Root stands on the ground (z 0.01-0.40), so it stays put
 'tripo::Spine_0':'pelvis_02','tripo::Spine_1':'spine_01_03','tripo::Spine_2':'spine_02_04','tripo::Spine_3':'spine_03_05',
 'tripo::Spine_4':'spine_03_05','tripo::Spine_5':'neck_01_018','tripo::Head_0':'head_019','tripo::Tail_0':'tail_01_032','tripo::Tail_1':'tail_03_034',
 'bone_11':'clavicle_L_06','bone_12':'upperarm_L_07','bone_13':'upperarm_L_07','L_fore':'lowerarm_L_08','L_paw':'hand_L_09',
 'bone_14':'clavicle_R_012','bone_15':'upperarm_R_013','bone_16':'lowerarm_R_014','bone_17':'hand_R_015','bone_18':'fingers_01_R_016',
 'bone_22':'spine_03_05','bone_23':'spine_03_05','bone_24':'thigh_L_037','bone_25':'cafl_L_038','bone_26':'foot_L_039','bone_27':'ball_L_040',
 'bone_3':'thigh_R_042','bone_4':'cafl_R_043','bone_5':'foot_R_044','bone_6':'ball_R_045',
}
RMAP={ # rider bone -> mixamo bone (clip is MIRRORED: rider left arm takes the clip's right arm = the fist-shaking one)
 'R_Hips':'mixamorig:Hips','R_Spine':'mixamorig:Spine','R_Spine1':'mixamorig:Spine1','R_Spine2':'mixamorig:Spine2','R_Neck':'mixamorig:Neck','R_Head':'mixamorig:Head',
 'R_LShoulder':'mixamorig:RightShoulder','R_LArm':'mixamorig:RightArm','R_LForeArm':'mixamorig:RightForeArm','R_LHand':'mixamorig:RightHand',
 # right arm (reins) stays at rest
}
_b=set(bpy.data.objects); _ba=set(bpy.data.actions); bpy.ops.import_scene.gltf(filepath=QW)
qnew=[o for o in bpy.data.objects if o not in _b]; qa=[o for o in qnew if o.type=='ARMATURE'][0]
acts=[a for a in bpy.data.actions if a not in _ba and a.name.lower().split('.')[0]==ACT]
print("WOLF actions", [a.name for a in bpy.data.actions if a not in _ba], "->", [a.name for a in acts], "range", tuple(acts[0].frame_range))
print("WOLF bones missing", [b for b in WMAP.values() if b not in qa.pose.bones])
if qa.animation_data:
    for t in list(qa.animation_data.nla_tracks): qa.animation_data.nla_tracks.remove(t)
else: qa.animation_data_create()
_f0,_f1=acts[0].frame_range
wolf_s=sample(qa,acts[0],[_f0+i*(_f1-_f0)/NF for i in range(NF)],list(WMAP.values()),'pelvis_02')
NXT={'upperarm_L_07':'lowerarm_L_08','lowerarm_L_08':'hand_L_09','hand_L_09':'fingers_01_L_010','fingers_01_L_010':'fingers_02_L_011',
 'upperarm_R_013':'lowerarm_R_014','lowerarm_R_014':'hand_R_015','hand_R_015':'fingers_01_R_016','fingers_01_R_016':'fingers_02_R_017',
 'thigh_L_037':'cafl_L_038','cafl_L_038':'foot_L_039','foot_L_039':'ball_L_040','ball_L_040':'Toe_L_041',
 'thigh_R_042':'cafl_R_043','cafl_R_043':'foot_R_044','foot_R_044':'ball_R_045','ball_R_045':'Toe_R_046'}
wolf_d=[]
for f in [_f0+i*(_f1-_f0)/NF for i in range(NF)]:
    fi=int(math.floor(f)); sc.frame_set(fi,subframe=f-fi); bpy.context.view_layer.update(); _Wq=qa.matrix_world
    wolf_d.append({k:(_Wq@qa.pose.bones[v].head-_Wq@qa.pose.bones[k].head).normalized() for k,v in NXT.items()})
print("BOB z", ["%.3f"%(s[1].z-wolf_s[0][1].z) for s in wolf_s])
sa,snew=import_fbx(SA,"SRC_RIDER")
sact=[a for a in bpy.data.actions if "mixamo" in a.name.lower()][0]
rider_s=sample(sa,sact,[1+i*(104/(NF-1)) for i in range(NF)],list(RMAP.values()),'mixamorig:Hips')
for o in qnew+snew: bpy.data.objects.remove(o,do_unlink=True)

# ---------- 4. retarget ----------
YAW=Matrix.Rotation(math.radians(90),3,'Z'); SX=Matrix.Diagonal((-1,1,1))
def delta(q,q0,mirror):
    D=q.to_matrix()@q0.to_matrix().transposed()
    if mirror: D=SX@D@SX
    return YAW@D@YAW.transposed()
def order():
    out=[]
    def rec(b):
        out.append(b); [rec(c) for c in b.children]
    [rec(b) for b in arm.data.bones if b.parent is None]; return out
DIRB=set(os.environ.get("DIRB","bone_12,bone_13,L_fore,L_paw,bone_15,bone_16,bone_17,bone_18,bone_3,bone_4,bone_5,bone_6,bone_24,bone_25,bone_26,bone_27").split(","))
RIDERUP=os.environ.get("RIDERUP","1")=="1"
BO=order(); Mw3=Mw.to_3x3().normalized(); expect={}
prevq={}
PREB=os.environ.get("PREB","R_LArm,R_LForeArm,R_LHand").split(",")
PRE={}
for n in PREB:
    src=RMAP[n]; b=arm.data.bones[n]
    mix0=YAW@(SX@(rider_s[0][0][src].to_matrix()@Vector((0,1,0))))
    mine=(Mw3@b.matrix_local.to_3x3().normalized())@Vector((0,1,0))
    PRE[n]=mine.normalized().rotation_difference(mix0.normalized()).to_matrix()
    print("PRE %s %.1f deg"%(n,math.degrees(PRE[n].to_quaternion().angle)))
for i in range(NF):
    F=i+1; posemat={}
    for b in BO:
        pb=arm.pose.bones[b.name]; rest=b.matrix_local
        chain=(posemat[b.parent.name]@b.parent.matrix_local.inverted()@rest) if b.parent else rest.copy()
        if b.name in WMAP: src,samp,mir,scale,root=WMAP[b.name],wolf_s,False,WSCALE,b.name=='tripo::Root'
        elif b.name=='R_Hips' and RIDERUP: src='__up'
        elif b.name in RMAP: src=None   # v6: orc sits calmly, no rider retarget
        else: src=None
        if src=='__up':
            Rdes=Mw3@rest.to_3x3().normalized(); D=Matrix.Translation(chain.translation)@(Mw3.transposed()@Rdes).to_4x4(); basis=chain.inverted()@D; expect[(F,b.name)]=Rdes; root=False
        elif src is None or src not in samp[i][0]:
            D=chain.copy(); basis=Matrix.Identity(4)
        else:
            Dw=delta(samp[i][0][src],samp[0][0][src],mir)
            Rdes=Dw@PRE.get(b.name,Matrix.Identity(3))@(Mw3@rest.to_3x3().normalized())
            if b.name in DIRB:
                R0=Mw3@rest.to_3x3().normalized(); sd=YAW@wolf_d[i][src]
                Rdes=(R0@Vector((0,1,0))).normalized().rotation_difference(sd.normalized()).to_matrix()@R0
            D=Matrix.Translation(chain.translation)@(Mw3.transposed()@Rdes).to_4x4()
            if root:
                t=samp[i][1]-samp[0][1]; t.x=0.0; t.y=0.0   # v7: run in place, keep the bob
                if mir: t=SX@t
                D.translation=D.translation+Mw3.transposed()@(YAW@t)*scale
            basis=chain.inverted()@D
            expect[(F,b.name)]=Rdes
        posemat[b.name]=D
        pb.rotation_mode='QUATERNION'; q=basis.to_quaternion()
        if b.name in prevq and q.dot(prevq[b.name])<0: q=-q
        prevq[b.name]=q; pb.rotation_quaternion=q; pb.keyframe_insert('rotation_quaternion',frame=F)
        if src is not None and root: pb.location=basis.translation; pb.keyframe_insert('location',frame=F)
sc.frame_start=1; sc.frame_end=NF
# verify
err=0; worst=None
for F in sorted({1,NF//4+1,NF//2+1,NF}):
    sc.frame_set(F); bpy.context.view_layer.update()
    for (f,n),R in expect.items():
        if f!=F: continue
        got=(arm.matrix_world@arm.pose.bones[n].matrix).to_3x3().normalized()
        a=math.degrees((got@R.transposed()).to_quaternion().angle)
        if a>err: err=a; worst=(F,n)
print("VERIFY max rot err deg %.3f at %s"%(err,worst))
for F in sorted({1,NF//4+1,NF//2+1,NF}):
    sc.frame_set(F); bpy.context.view_layer.update(); W=arm.matrix_world
    print("F%2d"%F, " ".join("%s=(%.2f,%.2f,%.2f)"%(k,*(W@arm.pose.bones[n].head)) for k,n in (("root","tripo::Root"),("head","tripo::Head_0"),("hips","R_Hips"),("Lhand","R_LHand"),("Rhand","R_RHand"),("rhead","R_Head"))))

# ---------- 4b. cut fused bridge faces ----------
# Tripo fused spear shaft, fist and wolf mane into one surface; faces that span rider- and wolf-driven verts
# stretch into planks when the arm lifts. Cut every face with an edge that stretches >2.5x rest (and >5 cm) in any frame.
rest=[v.co.copy() for v in me.vertices]
badE=set()
# v4: the fused contact seam (forearm/fist against belly, strap and mane) is a rider-internal edge, but it must cut when it stretches
own=lambda i: max(W[i],key=W[i].get) if i in W else None
LOW={"R_LForeArm","R_LHand","R_RForeArm","R_RHand"}; ARM=LOW|{"R_LArm","R_RArm"}
def contact(a,b):
    oa,ob_=own(a),own(b); return ((oa in LOW)!=(ob_ in LOW)) and not (oa in ARM and ob_ in ARM)
_ncut=0
for F in range(sc.frame_start,sc.frame_end+1):
    sc.frame_set(F); dg=bpy.context.evaluated_depsgraph_get(); ev=ob.evaluated_get(dg).data
    for e in me.edges:
        a,b=e.vertices; r=(rest[a]-rest[b]).length; c=(ev.vertices[a].co-ev.vertices[b].co).length
        if c>0.05 and c>2.5*max(r,1e-4) and min(rest[a].z,rest[b].z)>float(os.environ.get('CUTZ','0.3')) and not (a in candset and b in candset and not contact(a,b)): badE.add(e.index)   # v2: never cut the rider's own faces
import bmesh
bm=bmesh.new(); bm.from_mesh(me); bm.edges.ensure_lookup_table()
badF=set(f for ei in badE for f in bm.edges[ei].link_faces)
bz=[v.co.z for f in badF for v in f.verts]
print("CUT faces", len(badF), "of", len(bm.faces), "z %.2f..%.2f"%(min(bz),max(bz)) if bz else "")
bmesh.ops.delete(bm, geom=list(badF), context='FACES_ONLY')
# drop small face patches left floating by the cut (blended-weight slivers between arm and chest)
bm.faces.ensure_lookup_table(); _seen={}; _patches=[]
for _f0 in bm.faces:
    if _f0.index in _seen: continue
    _st=[_f0]; _seen[_f0.index]=1; _c=[]
    while _st:
        _f=_st.pop(); _c.append(_f)
        for _e in _f.edges:
            for _g in _e.link_faces:
                if _g.index not in _seen: _seen[_g.index]=1; _st.append(_g)
    _patches.append(_c)
_small=[f for c in _patches if len(c)<80 for f in c]
print("PATCHES", len(_patches), "dropped small faces", len(_small))
if _small: bmesh.ops.delete(bm, geom=_small, context='FACES_ONLY')
bm.to_mesh(me); bm.free(); me.update()

